Sys.setenv(STAT312_SLIDES_MODE = "1")
# In RStudio, open this file and click Run App.
# Course root: shiny::runApp("R_code/Hypothesis_Error_Demo")
# For the embedded slides, use Class19/Start_Class19_Slides.command (port 8766).
if (!requireNamespace("shiny", quietly = TRUE)) {
  stop('Install shiny once with install.packages("shiny") to run this instructor app.')
}
source("power_core.R", local = TRUE)
slides_mode <- identical(Sys.getenv("STAT312_SLIDES_MODE"), "1")

# The browser export contains the app alone, without the local lecture folder.
slide_directory <- file.path("..", "Class19")
if (dir.exists(slide_directory)) {
  shiny::addResourcePath("class19-slides", normalizePath(slide_directory))
}

ui <- shiny::fluidPage(
  shiny::tags$head(shiny::tags$style(shiny::HTML("
    body { color:#172b40; background:#fff; font-size:16px; }
    .container-fluid { max-width:1550px; padding:16px 26px; }
    h1 { font-size:29px; color:#003071; font-weight:600; margin-top:8px; }
    .lead-note { color:#425c72; margin-bottom:16px; }
    .well { background:#f4f7fa; border:0; box-shadow:none; padding:18px; }
    .control-label { font-size:15px; }
    .help-block,.plot-note { font-size:13px; color:#4b6071; }
    .plot-note { line-height:1.5; }
    .mode-message { font-size:17px; line-height:1.5; margin:8px 0 12px; }
    .legend-row { display:flex; flex-wrap:wrap; gap:18px; margin:8px 0; }
    .legend-item { display:inline-flex; align-items:center; gap:7px; font-size:14px; }
    .swatch { width:17px; height:12px; display:inline-block; }
    .swatch.alpha { background:#c44145; } .swatch.beta { background:#cf9528; }
    .quick-buttons { display:flex; gap:8px; flex-wrap:wrap; margin:8px 0 14px; }
    .quick-buttons .btn { font-size:13px; }
    details { margin:14px 0; } summary { cursor:pointer; font-weight:600; }
    .nav-tabs { margin:10px 0; }
    .table-wrap { overflow-x:auto; } .table { font-size:14px; }
    .table td,.table th { vertical-align:middle!important; }
    .tradeoff-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px; }
    .btn { white-space:normal; }
    .shiny-output-error-validation { color:#a33030; padding:12px 0; }
    @media(max-width:1000px) { .tradeoff-grid { grid-template-columns:1fr; } }
    @media(max-width:767px) { .container-fluid { padding:12px; } h1 { font-size:25px; } }
    body.slide-embed { font-size:14px; }
    .slide-embed .container-fluid { padding:6px 16px; }
    .slide-embed h1,.slide-embed .lead-note,.slide-embed #mode_message,
    .slide-embed .nav-tabs,.slide-embed .plot-note,.slide-embed .table-wrap,
    .slide-embed #interpretation,.slide-embed .main-panel-details { display:none; }
    .slide-embed .well { padding:10px; margin-bottom:0; }
    .slide-embed .control-label { font-size:13px; }
    .slide-embed .legend-row { gap:12px; margin:2px 0; }
    .slide-embed .legend-item { font-size:12px; }
    .slide-embed #distributions { height:420px!important; }
    .slide-embed .quick-buttons { margin:4px 0 8px; }
  ")),
    shiny::tags$script(shiny::HTML(paste0("
      document.addEventListener('DOMContentLoaded', function () {
        if (", if (slides_mode) "true" else "false", " ||
            new URLSearchParams(window.location.search).get('slides') === '1') {
          document.body.classList.add('slide-embed');
        }
      });
    ")))),
  shiny::h1("Propellant Burning Rate: Alpha and Beta in Motion"),
  shiny::p(class = "lead-note",
    "Class 18: compare the sampling distributions before and after changing the rejection rule or sample size."),
  shiny::sidebarLayout(
    shiny::sidebarPanel(width = 3,
      shiny::selectInput("experiment", "Demonstration", choices = c(
        "Alpha and beta" = "alpha", "Sample size: cutoffs fixed" = "n_cutoff",
        "Sample size: alpha fixed" = "n_alpha")),
      shiny::sliderInput("mu_alt", "Selected true mean (mu_a)",
        min = 46, max = 54, value = 52, step = 0.1),
      shiny::div(class = "quick-buttons",
        shiny::actionButton("large_shift", "mu_a = 52"),
        shiny::actionButton("small_shift", "mu_a = 50.5")),
      shiny::conditionalPanel("input.experiment === 'alpha'",
        shiny::radioButtons("alpha_control", "Change the rule by setting",
          choices = c("Cutoff distance from mu0" = "width", "Significance level alpha" = "alpha")),
        shiny::conditionalPanel("input.alpha_control === 'width'",
          shiny::sliderInput("current_width", "Current cutoff distance",
            min = 0.25, max = 3, value = 2, step = 0.05,
            animate = shiny::animationOptions(interval = 650, loop = FALSE)),
          shiny::helpText("Distance 1.5 gives [48.5, 51.5]; distance 2 gives [48, 52].")),
        shiny::conditionalPanel("input.alpha_control === 'alpha'",
          shiny::sliderInput("alpha_current", "Current alpha",
            min = 0.001, max = 0.2, value = 0.01, step = 0.001)),
        shiny::helpText("Both panels use the reference n. Only the critical boundaries move.")),
      shiny::conditionalPanel("input.experiment !== 'alpha'",
        shiny::sliderInput("current_n", "Current sample size (n)",
          min = 5, max = 100, value = 16, step = 1,
          animate = shiny::animationOptions(interval = 500, loop = FALSE)),
        shiny::conditionalPanel("input.experiment === 'n_alpha'",
          shiny::sliderInput("alpha_fixed", "Alpha in both panels",
            min = 0.001, max = 0.2, value = 0.05, step = 0.001))),
      shiny::tags$details(
        shiny::tags$summary("Reference model"),
        shiny::numericInput("mu0", "Null mean (mu0)", value = 50, step = 0.5),
        shiny::numericInput("sigma", "Known population SD", value = 2.5, min = 0.01, step = 0.1),
        shiny::numericInput("reference_n", "Reference sample size", value = 10, min = 1, step = 1),
        shiny::numericInput("reference_width", "Reference cutoff distance", value = 1.5, min = 0.01, step = 0.1)),
      shiny::tags$details(
        shiny::tags$summary("Plot options"),
        shiny::checkboxInput("reference_outline", "Show original curves in the lower panel", TRUE),
        shiny::checkboxInput("show_power", "Also shade the power region", FALSE)),
      shiny::actionButton("reset", "Reset propellant example"),
      shiny::hr(),
      shiny::downloadButton("download_plot", "Download comparison (PNG)"),
      shiny::br(), shiny::br(),
      shiny::downloadButton("download_csv", "Download settings and probabilities")
    ),
    shiny::mainPanel(width = 9,
      shiny::textOutput("mode_message", container = function(...) shiny::div(class = "mode-message", ...)),
      shiny::uiOutput("area_legend"),
      shiny::tabsetPanel(id = "view",
        shiny::tabPanel("Distribution comparison", value = "distributions",
          shiny::plotOutput("distributions", height = "630px"),
          shiny::p(class = "plot-note", "Blue: H0 distribution. Black: alternative distribution. Dashed red lines: critical boundaries. Both panels share the same x and y scales. Faint dotted curves in the lower panel show the original distributions when n changes.")),
        shiny::tabPanel("Probability curves", value = "tradeoffs",
          shiny::div(class = "tradeoff-grid",
            shiny::plotOutput("alpha_profile", height = "365px"),
            shiny::plotOutput("n_profile", height = "365px")),
          shiny::p(class = "plot-note", "Left: vary alpha at the current n. Right: vary n using the current rule. A cutoff-based current rule keeps its boundaries fixed; an alpha-based rule recalculates them."))),
      shiny::div(class = "table-wrap", shiny::tableOutput("comparison_table")),
      shiny::uiOutput("interpretation"),
      shiny::tags$details(class = "main-panel-details",
        shiny::tags$summary("Model and precision"),
        shiny::p("Independent normal observations, known population SD, and a two-sided Z-test. The null mean is 50 cm/sec by default. The alternative mean is a specified hypothetical population mean."),
        shiny::p("Population SD 2.5 gives SE = 0.79057 at n = 10 and SE = 0.625 at n = 16. The slides round the first SE to 0.79, so the displayed probabilities differ slightly from the rounded slide values."),
        shiny::p("A density curve always has total area one. Its height changes with the standard error. Alpha and beta describe areas, rather than curve heights or probabilities that a hypothesis is true.")))
  )
)

server <- function(input, output, session) {
  shiny::observeEvent(input$large_shift, {
    shiny::updateSliderInput(session, "mu_alt", value = input$mu0 + 2)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$small_shift, {
    shiny::updateSliderInput(session, "mu_alt", value = input$mu0 + 0.5)
  }, ignoreInit = TRUE)
  shiny::observeEvent(input$reset, {
    shiny::updateSelectInput(session, "experiment", selected = "alpha")
    shiny::updateRadioButtons(session, "alpha_control", selected = "width")
    shiny::updateSliderInput(session, "mu_alt", min = 46, max = 54, value = 52, step = 0.1)
    shiny::updateSliderInput(session, "current_width", value = 2)
    shiny::updateSliderInput(session, "current_n", value = 16)
    shiny::updateSliderInput(session, "alpha_current", value = 0.01)
    shiny::updateSliderInput(session, "alpha_fixed", value = 0.05)
    shiny::updateNumericInput(session, "mu0", value = 50)
    shiny::updateNumericInput(session, "sigma", value = 2.5)
    shiny::updateNumericInput(session, "reference_n", value = 10)
    shiny::updateNumericInput(session, "reference_width", value = 1.5)
    shiny::updateCheckboxInput(session, "reference_outline", value = TRUE)
    shiny::updateCheckboxInput(session, "show_power", value = FALSE)
  }, ignoreInit = TRUE)
  shiny::observeEvent(list(input$mu0, input$sigma), {
    shiny::req(is.finite(input$mu0), is.finite(input$sigma), input$sigma > 0)
    selected <- if (is.null(input$mu_alt)) input$mu0 + 2 else input$mu_alt
    span <- max(4, 2 * input$sigma)
    selected <- max(input$mu0 - span, min(input$mu0 + span, selected))
    shiny::updateSliderInput(session, "mu_alt", min = input$mu0 - span,
      max = input$mu0 + span, value = selected, step = min(0.1, input$sigma / 10))
  }, ignoreInit = TRUE)

  comparison <- shiny::reactive({
    shiny::req(input$experiment, input$alpha_control, !is.null(input$mu_alt),
      !is.null(input$mu0), !is.null(input$sigma), !is.null(input$reference_n),
      !is.null(input$reference_width), !is.null(input$current_n),
      !is.null(input$current_width), !is.null(input$alpha_current), !is.null(input$alpha_fixed))
    tryCatch(propellant_comparison(
      mu0 = input$mu0, mu_alt = input$mu_alt, sigma = input$sigma,
      reference_n = input$reference_n, current_n = input$current_n,
      reference_width = input$reference_width, current_width = input$current_width,
      alpha_control = input$alpha_control, alpha_current = input$alpha_current,
      alpha_fixed = input$alpha_fixed, experiment = input$experiment),
      error = function(error) shiny::validate(shiny::need(FALSE, conditionMessage(error))))
  })
  current <- shiny::reactive(comparison()$current)
  alpha_curve <- shiny::reactive({
    maximum <- max(0.2, min(0.999, current()$alpha * 1.05))
    normal_test_profile(comparison()$current_parameters, "alpha", seq(0.001, maximum, length.out = 200))
  })
  n_curve <- shiny::reactive({
    normal_test_profile(comparison()$current_parameters, "n", 5:100)
  })

  output$mode_message <- shiny::renderText({
    result <- comparison()
    switch(result$experiment,
      alpha = "The distribution shapes stay the same. Moving the critical boundaries changes the red alpha area and gold beta area.",
      n_cutoff = "The cutoffs stay fixed. Increasing n narrows both distributions; the red and gold areas can change in different directions.",
      n_alpha = "Alpha stays fixed. Increasing n narrows both distributions and moves the cutoffs toward the null mean.")
  })
  output$area_legend <- shiny::renderUI({
    alternative <- current()$is_alternative
    entries <- shiny::tagList(
      shiny::span(class = "legend-item", shiny::span(class = "swatch alpha"),
        "Type I error: area under H0 outside the cutoffs"),
      shiny::span(class = "legend-item", shiny::span(class = "swatch beta"),
        if (alternative) "Type II error: area under Ha inside the cutoffs" else
          "Nonrejection at the selected null mean"))
    if (isTRUE(input$show_power)) {
      entries <- shiny::tagList(entries,
        shiny::span(class = "legend-item",
          shiny::span(class = "swatch", style = "background:#137b6d"),
          if (alternative) "Power: rejection area under Ha" else "Rejection at the null mean"))
    }
    shiny::div(class = "legend-row", entries)
  })
  output$comparison_table <- shiny::renderTable(comparison_table(comparison()),
    rownames = FALSE, digits = 4, striped = FALSE, bordered = FALSE, spacing = "s", na = "Not applicable")
  output$interpretation <- shiny::renderUI({
    selected <- comparison()
    result <- selected$current
    content <- if (!result$is_alternative) {
      "The selected mean equals the null mean. Gold is the nonrejection probability, not a Type II error. Rejection probability equals alpha."
    } else if (selected$experiment == "alpha") {
      "A wider nonrejection interval makes alpha smaller and beta larger at the same n. The curves do not change shape because the sampling model stays the same."
    } else if (selected$experiment == "n_alpha") {
      "With the significance level held fixed, increasing n reduces beta for any fixed alternative mean different from the null mean. The critical interval narrows to keep alpha unchanged."
    } else if (result$mu_alt > result$lower && result$mu_alt < result$upper) {
      "The alternative mean is inside the fixed nonrejection interval. As n becomes large, its sampling distribution concentrates inside that interval: beta tends to 1 and power tends to 0."
    } else if (result$mu_alt == result$lower || result$mu_alt == result$upper) {
      "The alternative mean equals a fixed boundary. As n becomes large, about half the alternative distribution remains inside the interval, so beta tends to 0.5."
    } else {
      "The alternative mean is outside the fixed nonrejection interval. As n becomes large, its sampling distribution concentrates outside that interval: beta tends to 0 and power tends to 1."
    }
    shiny::div(class = "mode-message", shiny::p(content),
      shiny::p(class = "plot-note", "Source: Class18_STAT312_FA26.pdf, propellant example, PDF pages 12 and 15-17. Areas use full-precision normal probabilities, including the complete tails."))
  })
  output$distributions <- shiny::renderPlot({
    compact <- slides_mode ||
      isTRUE(grepl("(^|[?&])slides=1(&|$)", session$clientData$url_search))
    plot_propellant_comparison(comparison(), isTRUE(input$show_power),
                              isTRUE(input$reference_outline), compact = compact)
  }, res = 110, alt = "Reference and changed settings, each overlaying null and alternative distributions, with red Type I error and gold Type II error areas.")
  output$alpha_profile <- shiny::renderPlot(plot_test_profile(alpha_curve(), current(), "alpha"),
    res = 110, alt = "Alpha-beta tradeoff at the current sample size.")
  output$n_profile <- shiny::renderPlot(plot_test_profile(n_curve(), current(), "n"),
    res = 110, alt = "Actual alpha, beta, and power versus sample size for the current test rule.")
  output$download_plot <- shiny::downloadHandler(
    filename = function() "STAT312_propellant_comparison.png",
    content = function(file) {
      png(file, width = 1700, height = 1150, res = 145)
      on.exit(dev.off())
      plot_propellant_comparison(comparison(), isTRUE(input$show_power), isTRUE(input$reference_outline))
    }, contentType = "image/png")
  output$download_csv <- shiny::downloadHandler(
    filename = function() "STAT312_propellant_comparison.csv",
    content = function(file) {
      selected <- comparison()
      rows <- lapply(c("reference", "current"), function(name) {
        x <- selected[[name]]
        data.frame(setting = name, experiment = selected$experiment, mu0 = x$mu0,
          mu_alt = x$mu_alt, sigma = x$sigma, n = x$n, se = x$se,
          lower = x$lower, upper = x$upper, alpha = x$alpha, beta = x$beta,
          rejection_probability = x$power, nonrejection_probability = x$nonrejection,
          rule = x$rule, nominal_alpha = x$nominal_alpha)
      })
      write.csv(do.call(rbind, rows), file, row.names = FALSE)
    }, contentType = "text/csv")
}

shiny::shinyApp(ui = ui, server = server)
